import{_ as s,o as a,c as t,ax as n}from"./chunks/framework.Bnt0oLax.js";const m=JSON.parse('{"title":"Response Transformation","description":"Response transformation reference — the Response Body and Response Content-Type fields, the response variables available to templates, and response template error handling","frontmatter":{"description":"Response transformation reference — the Response Body and Response Content-Type fields, the response variables available to templates, and response template error handling"},"headers":[],"relativePath":"connectors/response-transformation.md","filePath":"connectors/response-transformation.md"}'),o={name:"connectors/response-transformation.md"};function i(r,e,l,p,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/connectors/response-transformation.md for this page in Markdown format</div><h1 id="response-transformation" tabindex="-1">Response Transformation <a class="header-anchor" href="#response-transformation" aria-label="Permalink to &quot;Response Transformation&quot;">​</a></h1><p>A <a href="https://jinja.palletsprojects.com/" target="_blank" rel="noreferrer">Jinja2</a> template applied to the upstream API response body before it is returned to the widget — letting you filter, reshape, or reformat responses on the server.</p><p>The template applies to the <strong>incoming response body only</strong> — it has no effect on the outgoing request. If the field is blank, the original upstream response is returned as-is.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><h3 id="response-body" tabindex="-1">Response Body <a class="header-anchor" href="#response-body" aria-label="Permalink to &quot;Response Body&quot;">​</a></h3><p>A <a href="https://jinja.palletsprojects.com/" target="_blank" rel="noreferrer">Jinja2</a> template applied to the upstream API response. The template has access to the full response body, status code, and headers.</p><p>If blank or not set, the upstream response is passed through unchanged.</p><h3 id="response-content-type" tabindex="-1">Response Content-Type <a class="header-anchor" href="#response-content-type" aria-label="Permalink to &quot;Response Content-Type&quot;">​</a></h3><p>Overrides the <code>Content-Type</code> header on the response returned to the widget. If blank, the upstream API&#39;s original <code>Content-Type</code> is preserved.</p><p>Set this when your template changes the output format — for example, if the upstream API returns XML but your template produces JSON, set this to <code>application/json</code>.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For the full list of variables, filters, and functions available in templates, see <a href="./template-variables.html">Template Variables</a>.</p></div><p>Three variables are specific to response templates:</p><ul><li><strong><code>response.body</code></strong> — the upstream response body as a decoded UTF-8 string. If the response is not valid UTF-8 (e.g. binary content), this is <code>None</code>.</li><li><strong><code>response.status_code</code></strong> — the HTTP status code from the upstream API (integer).</li><li><strong><code>response.headers</code></strong> — the response headers from the upstream API as a dictionary. Header names are lowercase (e.g., <code>content-type</code>, not <code>Content-Type</code>).</li></ul><p>Also available: <code>user.*</code> fields, <code>tenant_id</code>, <code>now()</code>, and filters such as <code>from_json</code>, <code>json_encode</code>, <code>tojson</code>, <code>base64_encode</code>, and <code>base64_decode</code> — standard Jinja2 built-in filters (e.g. <code>selectattr</code>, <code>list</code>) are available too.</p><div class="warning custom-block"><p class="custom-block-title">get_secret() is not available here</p><p>Response templates do not have access to <code>{{ get_secret() }}</code>. Response output is returned to the browser, so secrets are excluded to prevent accidental leakage. Use headers or query parameters if you need to include secret values in the request to the upstream API. See <a href="./secrets/">Secrets and Variables</a> for details.</p></div><div class="warning custom-block"><p class="custom-block-title">jwt_encode() is not available here</p><p>Response templates do not have access to <code>jwt_encode()</code>. JWTs are used for authenticating outgoing requests, not for shaping response data.</p></div><div class="warning custom-block"><p class="custom-block-title">body_text and body_raw are not available</p><p><code>{{ body_text }}</code> and <code>{{ body_raw }}</code> are not available in response templates. These variables represent the incoming request body — use <code>response.body</code> to access the upstream API&#39;s response.</p></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p><strong>Extract specific fields from a large response:</strong></p><div class="language-jinja2 vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja2</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">{%</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.body | from_json </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">%}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;id&quot;: </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">id</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> }}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;name&quot;: &quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> }}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;status&quot;: &quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> }}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>For more worked examples — handling errors by status code, including user context, and other common transformations — see <a href="./response-transformation-recipes.html">Response Transformation Recipes</a>.</p><div class="danger custom-block"><p class="custom-block-title">Do not output from_json directly</p><p>Never use <code>{{ response.body | from_json }}</code> as the entire response template — it produces HTML-escaped Python notation, not valid JSON. Leave the field blank to forward the response as-is, or use <code>{% set %}</code> to extract specific fields. See <a href="./template-variables.html#behavioral-notes">Template Variables — Behavioral notes</a> for details.</p></div><h2 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h2><p>If the response template fails to render (e.g. syntax error, type mismatch), the connector returns HTTP 422 with a JSON error envelope whose <code>errors.scope</code> is &quot;Configuration (response template rendering)&quot;. This is separate from request template errors, which use &quot;Configuration (template rendering)&quot;.</p><p>The response template runs on all upstream status codes — including 4xx and 5xx errors. This means you can normalize error responses from different APIs into a consistent format for your widget.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./response-transformation-recipes.html">Response Transformation Recipes</a> — Worked examples and common gotchas for reshaping, filtering, and resolving response data</li><li><a href="./calling-from-widgets.html">Calling from Widget Code</a> — Use connectors with response transformation in your widget</li><li><a href="./filtering-sensitive-data.html">Filtering Sensitive Data</a> — Use response templates to keep hidden records out of the browser</li><li><a href="./template-variables.html">Template Variables</a> — Full reference for Jinja2 variables, filters, and functions</li><li><a href="https://jinja.palletsprojects.com/en/stable/templates/" target="_blank" rel="noreferrer">Jinja2 Template Designer Docs</a> — official reference for Jinja2 syntax: loops, conditionals, filters, and <code>namespace</code></li><li><a href="./configuration.html">Configuration</a> — Overview of all connector fields</li><li><a href="./payload-template.html">Request Transformation</a> — Reshape outgoing request bodies with Jinja2</li></ul>`,29)])])}const u=s(o,[["render",i]]);export{m as __pageData,u as default};
